  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT level, left(message,200) AS msg, count(*) AS n FROM abnormal_logs WHERE service_name='ts-order-other-service' AND level IN ('ERROR','SEVERE','WARN') GROUP BY 1,2 ORDER BY n DESC",
          "claim": "Order-other logs show Hikari 'Connection is not available, request timed out after 30000ms' and 'Communications link failure' DB errors, absent in normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(case when attr_status_code='Error' then 1 else 0 end) errs FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='ts-order-other-service' AND span_name IN ('SELECT Order','OrderOtherRepository.findByAccountId') GROUP BY 1,2 ORDER BY 2,1",
          "claim": "DB spans in order-other rose from ~2 ms p95 to ~30 s, with 29 of 34 'SELECT Order' spans erroring in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'norm' p, metric, round(avg(try_cast(value AS DOUBLE)),2) v FROM normal_metrics_sum WHERE service_name='ts-order-other-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.timeouts') GROUP BY 1,2 UNION ALL SELECT 'abn', metric, round(avg(try_cast(value AS DOUBLE)),2) FROM abnormal_metrics_sum WHERE service_name='ts-order-other-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.timeouts') GROUP BY 1,2",
          "claim": "Order-other DB connection pending requests rose from 0 to 4.5 and timeouts reached 6.5 in the abnormal period."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_source, attr_destination, metric, round(avg(try_cast(value AS DOUBLE)),2) v FROM abnormal_metrics_sum WHERE metric IN ('hubble_flows_processed_total','hubble_drop_total') AND (attr_source LIKE '%order-other%' AND attr_destination LIKE '%mysql%' OR attr_source LIKE '%mysql%' AND attr_destination LIKE '%order-other%') GROUP BY ALL",
          "claim": "Order-other to mysql connection shows flows but no drop counters, so the wire path looks intact and the fault is in the DB calls."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-seat-service",
